/**
 * Baseline metric import for the admin database (npm run db:import).
 *
 * Generates the one-off SQL that loads the published snapshot's metrics into
 * an empty public.metrics, and proves offline that the import reproduces the
 * site exactly. It never connects to Supabase and never applies anything: the
 * generated file is applied by hand, once, after the migrations, and only
 * before any publishing (Phase 3F-5).
 *
 *   node --import ./scripts/snapshot/register.mjs scripts/db/import-snapshot.mjs [--write]
 *
 * Verification (always): applies the shim, every migration and the generated
 * SQL to an in-memory PGlite database, then checks that
 *   * every snapshot metric exists with the same fields;
 *   * every value the admin would show equals the value the site renders;
 *   * nothing is marked verified or archived by the import;
 *   * the rows stay invisible to a signed-in non-admin.
 *
 * --write also saves the SQL to supabase/imports/metrics_baseline.sql.
 */
import { PGlite } from '@electric-sql/pglite';
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { resolveValues } from '../../admin/lib/metrics/values.ts';

const root = fileURLToPath(new URL('../../', import.meta.url));
const write = process.argv.includes('--write');

let failures = 0;
const ok = (message) => console.log(`PASS  ${message}`);
const fail = (message) => {
  failures += 1;
  console.log(`FAIL  ${message}`);
};

const snapshot = JSON.parse(readFileSync(join(root, 'snapshot', 'baseline.json'), 'utf8'));

// ---------------------------------------------------------------------------
// Generate
// ---------------------------------------------------------------------------

const literal = (value) => {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'number') return String(value);
  return `'${String(value).replace(/'/g, "''")}'`;
};
const jsonLiteral = (value) => (value === null || value === undefined ? 'null' : `${literal(JSON.stringify(value))}::jsonb`);

const formulaInputs = (formula) =>
  formula
    ? Object.entries(formula)
        .filter(([name]) => name !== 'fn')
        .flatMap(([, value]) => (Array.isArray(value) ? value : [value]))
    : [];

/** Inputs before the formulas that read them, so every insert passes the database's checks. */
function inDependencyOrder(metrics) {
  const ordered = [];
  const done = new Set();
  const pending = [...metrics];
  while (pending.length > 0) {
    const index = pending.findIndex((metric) => formulaInputs(metric.formula).every((key) => done.has(key)));
    if (index === -1) throw new Error('snapshot formulas cannot be ordered: a dependency is missing or circular');
    const [metric] = pending.splice(index, 1);
    ordered.push(metric);
    done.add(metric.id);
  }
  return ordered;
}

const COLUMNS = [
  'metric_key', 'name', 'description', 'kind', 'value_type', 'unit', 'currency', 'value', 'precision',
  'display_format', 'formula', 'evidence_status', 'data_origin', 'source_platform', 'source_type',
  'legacy_method_note', 'reporting_period_basis', 'reporting_period_start', 'reporting_period_end',
  'reporting_period_note',
];

const values = (metric) => [
  literal(metric.id),
  literal(metric.name),
  literal(metric.description),
  literal(metric.kind),
  literal(metric.valueType),
  literal(metric.unit),
  literal(metric.currency),
  literal(metric.value),
  literal(metric.precision),
  literal(metric.displayFormat),
  jsonLiteral(metric.formula),
  literal(metric.evidenceStatus),
  literal(metric.dataOrigin),
  literal(metric.sourcePlatform),
  literal(metric.sourceType),
  literal(metric.legacyMethodNote),
  literal(metric.reportingPeriod.basis),
  literal(metric.reportingPeriod.start),
  literal(metric.reportingPeriod.end),
  literal(metric.reportingPeriod.description),
];

const ordered = inDependencyOrder(snapshot.metrics);

const sql = `-- =====================================================================
-- Baseline metric import — generated by scripts/db/import-snapshot.mjs
-- Source: snapshot/baseline.json (${snapshot.metrics.length} metrics)
--
-- Apply ONCE, by hand, as the database owner, after every migration and
-- before any publishing. This is not a migration and must not be applied
-- automatically.
--
-- Private fields (source_reference, attribution_setting, internal_note) are
-- not in the snapshot and stay empty. No metric is marked verified: the
-- verification record is only ever written by a person confirming a figure
-- against its source, so every imported metric starts as "Not verified".
-- The import writes one version-history row and one audit entry per metric.
-- =====================================================================

begin;

do $$
begin
  if exists (select 1 from public.metrics) then
    raise exception 'public.metrics is not empty; review before importing the baseline';
  end if;
end
$$;

insert into public.metrics (${COLUMNS.join(', ')})
values
${ordered.map((metric) => `  (${values(metric).join(', ')})`).join(',\n')};

do $$
declare
  v_count integer;
begin
  select count(*) into v_count from public.metrics;
  if v_count <> ${snapshot.metrics.length} then
    raise exception 'expected ${snapshot.metrics.length} metrics after import, found %', v_count;
  end if;
end
$$;

commit;
`;

if (write) {
  const directory = join(root, 'supabase', 'imports');
  mkdirSync(directory, { recursive: true });
  const target = join(directory, 'metrics_baseline.sql');
  writeFileSync(target, sql);
  ok(`generated supabase/imports/metrics_baseline.sql (${snapshot.metrics.length} metrics)`);
} else {
  ok(`generated the import SQL in memory (${snapshot.metrics.length} metrics; pass --write to save it)`);
}

// ---------------------------------------------------------------------------
// Verify offline
// ---------------------------------------------------------------------------

const db = new PGlite();
await db.exec(readFileSync(join(root, 'scripts', 'db', 'supabase-shim.sql'), 'utf8'));
for (const name of readdirSync(join(root, 'supabase', 'migrations')).filter((file) => file.endsWith('.sql')).sort()) {
  await db.exec(readFileSync(join(root, 'supabase', 'migrations', name), 'utf8'));
}

try {
  await db.exec(sql);
  ok('the import applies to a database built from the migrations');
} catch (error) {
  fail(`the import was rejected: ${error.message}`);
  process.exit(1);
}

const { rows } = await db.query('select to_jsonb(m) as row from public.metrics m');
const imported = rows.map((item) => item.row);
const byKey = new Map(imported.map((metric) => [metric.metric_key, metric]));

if (imported.length === snapshot.metrics.length) ok(`${imported.length} metrics imported`);
else fail(`imported ${imported.length} metrics, expected ${snapshot.metrics.length}`);

/** JSON with object keys sorted, so two equal values always compare equal. */
const canonical = (value) =>
  JSON.stringify(value ?? null, (_key, item) =>
    item && typeof item === 'object' && !Array.isArray(item)
      ? Object.fromEntries(Object.entries(item).sort(([a], [b]) => a.localeCompare(b)))
      : item,
  );

const fieldProblems = [];
for (const metric of snapshot.metrics) {
  const row = byKey.get(metric.id);
  if (!row) {
    fieldProblems.push(`${metric.id}: missing`);
    continue;
  }
  const expected = {
    name: metric.name,
    description: metric.description,
    kind: metric.kind,
    value_type: metric.valueType,
    unit: metric.unit,
    currency: metric.currency,
    value: metric.value,
    precision: metric.precision,
    display_format: metric.displayFormat,
    evidence_status: metric.evidenceStatus,
    data_origin: metric.dataOrigin,
    source_platform: metric.sourcePlatform,
    source_type: metric.sourceType,
    legacy_method_note: metric.legacyMethodNote,
    reporting_period_basis: metric.reportingPeriod.basis,
    reporting_period_start: metric.reportingPeriod.start,
    reporting_period_end: metric.reportingPeriod.end,
    reporting_period_note: metric.reportingPeriod.description,
    formula: metric.formula,
  };
  for (const [field, want] of Object.entries(expected)) {
    const got = field === 'value' && row[field] !== null ? Number(row[field]) : row[field];
    // jsonb does not keep key order, so formulas are compared by content.
    if (canonical(got) !== canonical(want)) {
      fieldProblems.push(`${metric.id}.${field}: ${JSON.stringify(got)} ≠ ${JSON.stringify(want)}`);
    }
  }
}
if (fieldProblems.length === 0) ok('every imported metric matches the snapshot field for field');
else fail(`fields differ:\n      ${fieldProblems.slice(0, 10).join('\n      ')}${fieldProblems.length > 10 ? `\n      …and ${fieldProblems.length - 10} more` : ''}`);

// Values are compared against the TypeScript source of record, not the
// snapshot the import was generated from, so this catches a drifted snapshot
// as well as a bad import. (Loaded after setting CONTENT_SOURCE, because the
// registry reads it when it loads.)
process.env.CONTENT_SOURCE = 'typescript';
const { metricValue } = await import('../../lib/metrics/registry.ts');

const resolved = resolveValues(imported.map((row) => ({ ...row, value: row.value === null ? null : Number(row.value) })));
const valueProblems = [];
for (const metric of snapshot.metrics) {
  const admin = resolved.get(metric.id) ?? null;
  const site = metricValue(metric.id);
  if (admin !== site) valueProblems.push(`${metric.id}: admin ${admin} ≠ site ${site}`);
}
if (valueProblems.length === 0) ok(`all ${snapshot.metrics.length} values match the site's TypeScript source of record`);
else fail(`values differ:\n      ${valueProblems.slice(0, 10).join('\n      ')}`);

const graded = imported.filter((metric) => metric.verified_at !== null || metric.verification_source !== null);
if (graded.length === 0) ok('no metric is marked verified by the import');
else fail(`${graded.length} metrics were marked verified by the import`);

const archived = imported.filter((metric) => metric.archived_at !== null);
if (archived.length === 0) ok('no metric is archived by the import');
else fail(`${archived.length} metrics were archived by the import`);

const history = await db.query('select count(*)::int as count from public.metric_versions');
const audit = await db.query("select count(*)::int as count from public.audit_log where action = 'metric.insert'");
if (history.rows[0].count === imported.length && audit.rows[0].count === imported.length) {
  ok(`the import is recorded: ${history.rows[0].count} version rows and ${audit.rows[0].count} audit entries`);
} else {
  fail(`history ${history.rows[0].count} and audit ${audit.rows[0].count} do not match ${imported.length} metrics`);
}

const hidden = await db.transaction(async (tx) => {
  await tx.query("select set_config('request.jwt.claims', $1, true)", [
    JSON.stringify({ sub: '00000000-0000-4000-8000-0000000000ff', role: 'authenticated', aal: 'aal2' }),
  ]);
  await tx.exec('set local role authenticated');
  const visible = await tx.query('select count(*)::int as count from public.metrics');
  return visible.rows[0].count;
});
if (hidden === 0) ok('imported metrics stay invisible to a signed-in non-admin');
else fail(`a signed-in non-admin can see ${hidden} imported metrics`);

await db.close();
console.log(failures === 0 ? '\nBaseline import verified (nothing was applied to any project).' : `\nBaseline import check failed (${failures}).`);
process.exit(failures === 0 ? 0 : 1);
